//! Windows-only executable resources (app icon).
//!
//! The `BS` monogram lives in `assets/book-save.ico` (generated by
//! `assets/make-icon.ps1`, no runtime or package dependencies) and is linked
//! into the Windows exe via the Windows SDK resource compiler. Non-Windows
//! builds skip this step.

fn main() {
    #[cfg(windows)]
    let _ = embed_resource::compile("assets/book-save.rc", embed_resource::NONE);
}
